begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok((select not enabled and not enrollment and not discovery and not publish and not engagement and not delivery and cohort_required from public.community_operations),'Fresh environment starts with admission and delivery closed');
insert into auth.users(id,email) values
('c1900000-0000-4000-8000-000000000001','read-owner@mizyun.test'),
('c1900000-0000-4000-8000-000000000002','read-friend@mizyun.test'),
('c1900000-0000-4000-8000-000000000003','read-outsider@mizyun.test');
update public.profiles set birth_year=1990 where id::text like 'c1900000-%';
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='c1900000-0000-4000-8000-000000000003';
select throws_ok($$select * from public.community_save_profile('read_outsider','Outsider','OU',null,false,true,'2026-09-30')$$,'P0001','community_unavailable','Fresh authenticated direct enrollment cannot bypass closed admission');
reset role;set local request.jwt.claim.role='service_role';
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true;
insert into public.community_pilot_cohort(user_id) values('c1900000-0000-4000-8000-000000000001'),('c1900000-0000-4000-8000-000000000002');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select throws_ok($$select * from public.community_save_profile('read_outsider','Outsider','OU',null,false,true,'2026-09-30')$$,'P0001','community_unavailable','Explicit activation still excludes an unadmitted principal');
set local request.jwt.claim.sub='c1900000-0000-4000-8000-000000000001';
select * from public.community_save_profile('read_owner','Owner','OW',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='c1900000-0000-4000-8000-000000000002';
select * from public.community_save_profile('read_friend','Friend','FR',null,true,true,'2026-09-30');
reset role;set local request.jwt.claim.role='service_role';set local request.jwt.claim.role='service_role';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c1900000-0000-4000-8000-000000000002','c1900000-0000-4000-8000-000000000001','approved');
insert into public.workouts(id,user_id,name,started_at,completed_at,details) values('d1900000-0000-4000-8000-000000000001','c1900000-0000-4000-8000-000000000001','Private',now()-interval '1 hour',now(),'{"workoutLifecycle":{"kind":"session"}}');
insert into public.shared_activities(user_id,source_workout_id,category,shared_day) values('c1900000-0000-4000-8000-000000000001','d1900000-0000-4000-8000-000000000001','strength',(now() at time zone 'UTC')::date::text);
insert into public.community_invitations(inviter_user_id,token) values('c1900000-0000-4000-8000-000000000001','read-control-synthetic-token');
insert into public.community_relationships(follower_user_id,target_user_id,status) values
('c1900000-0000-4000-8000-000000000001','c1900000-0000-4000-8000-000000000002','pending'),
('c1900000-0000-4000-8000-000000000001','c1900000-0000-4000-8000-000000000003','pending');
insert into public.community_reactions(activity_id,user_id,reaction) select id,'c1900000-0000-4000-8000-000000000002','clap' from public.shared_activities where user_id='c1900000-0000-4000-8000-000000000001';
create temporary table read_control_state as select id as activity_id from public.shared_activities where user_id='c1900000-0000-4000-8000-000000000001';
alter table read_control_state add column receipt uuid;
grant all on read_control_state to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='c1900000-0000-4000-8000-000000000002';
select is((select count(*) from public.community_feed(20,null,null)),1::bigint,'Admitted follower sees one card');
update read_control_state set receipt=(select id from public.community_issue_report_receipt('profile','c1900000-0000-4000-8000-000000000001'));
reset role;set local request.jwt.claim.role='service_role';update public.community_operations set discovery=false;
set local role authenticated;set local request.jwt.claim.role='authenticated';
select throws_ok($$select * from public.community_resolve_invitation('read-control-synthetic-token')$$,'P0001','community_unavailable','Discovery freeze denies bearer resolution directly');
select throws_ok($$select * from public.community_resolve_invitation_ungated('read-control-synthetic-token')$$,'42501',null,'Renamed resolver cannot bypass its gate');
reset role;set local request.jwt.claim.role='service_role';update public.community_operations set discovery=true;
delete from public.community_pilot_cohort where user_id='c1900000-0000-4000-8000-000000000002';
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select count(*) from public.community_feed(20,null,null)),0::bigint,'Removed cohort viewer loses feed');
select is((select count(*) from public.shared_activities),0::bigint,'Removed cohort viewer loses direct table reads');
select is((select count(*) from public.community_get_profile('c1900000-0000-4000-8000-000000000001')),0::bigint,'Removed cohort viewer loses social identity');
reset role;set local request.jwt.claim.role='service_role';insert into public.community_pilot_cohort(user_id) values('c1900000-0000-4000-8000-000000000002');
update public.community_operations set enabled=false;
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((select count(*) from public.community_feed(20,null,null)),0::bigint,'Global freeze stops feed reads');
select is((select count(*) from public.shared_activities),0::bigint,'Global freeze stops direct shared-card reads');
select lives_ok($$update public.community_relationships set status='declined' where follower_user_id='c1900000-0000-4000-8000-000000000001' and target_user_id=auth.uid()$$,'Freeze preserves recipient decline');
select is((select status from public.community_relationships where follower_user_id='c1900000-0000-4000-8000-000000000001' and target_user_id=auth.uid()),'declined','Decline actually updates the pending edge');
select lives_ok($$delete from public.community_reactions where user_id=auth.uid()$$,'Freeze permits own unreact');
reset role;set local request.jwt.claim.role='service_role';
select is((select count(*) from public.community_reactions where user_id='c1900000-0000-4000-8000-000000000002'),0::bigint,'Own reaction is actually removed without browsing authority');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select lives_ok($$select public.community_set_mute('c1900000-0000-4000-8000-000000000001',true)$$,'Global freeze preserves mute privacy reduction');
select lives_ok($$select * from public.community_submit_report('profile','c1900000-0000-4000-8000-000000000001','harassment',null,(select receipt from read_control_state))$$,'Global freeze preserves receipt-backed reporting');
select lives_ok($$select * from public.community_export_page('identity')$$,'Global freeze preserves account export');
select lives_ok($$delete from public.community_relationships where follower_user_id=auth.uid() and target_user_id='c1900000-0000-4000-8000-000000000001'$$,'Freeze preserves unfollow');
select lives_ok($$insert into public.community_blocks(blocker_user_id,blocked_user_id) values(auth.uid(),'c1900000-0000-4000-8000-000000000001')$$,'Global freeze preserves blocking');
select lives_ok($$select public.community_withdraw_profile()$$,'Global freeze preserves withdrawal');
set local request.jwt.claim.sub='c1900000-0000-4000-8000-000000000001';
select lives_ok($$update public.community_relationships set status='canceled' where follower_user_id=auth.uid() and target_user_id='c1900000-0000-4000-8000-000000000003'$$,'Freeze preserves sender cancel');
select is((select status from public.community_relationships where follower_user_id=auth.uid() and target_user_id='c1900000-0000-4000-8000-000000000003'),'canceled','Cancel actually updates the pending edge');
select lives_ok($$select public.community_unpublish_activity((select activity_id from read_control_state),1)$$,'Freeze preserves owner unpublish');
reset role;set local request.jwt.claim.role='service_role';
select ok((select revoked_at is not null from public.shared_activities where id=(select activity_id from read_control_state)),'Unpublish actually revokes the card');
select * from finish();rollback;
